import { UnauthorizedException } from '@nestjs/common';
import { JwtAuthGuard } from './jwt-auth.guard';

function contextWithAuthorization(authorization?: string) {
  const request = { headers: { authorization }, user: undefined };
  return {
    request,
    context: {
      switchToHttp: () => ({
        getRequest: () => request,
      }),
    },
  };
}

describe('JwtAuthGuard', () => {
  it('attaches verified JWT payload to request user', async () => {
    const jwtService = {
      verifyAsync: jest.fn().mockResolvedValue({ sub: 'user-1', role: 'ADMIN' }),
    };
    const guard = new JwtAuthGuard(jwtService as never);
    const { request, context } = contextWithAuthorization('Bearer token');

    await expect(guard.canActivate(context as never)).resolves.toBe(true);
    expect(jwtService.verifyAsync).toHaveBeenCalledWith('token');
    expect(request.user).toEqual({
      sub: 'user-1',
      role: 'ADMIN',
      activeCompanyId: null,
    });
  });

  it('rejects missing bearer token', async () => {
    const guard = new JwtAuthGuard({ verifyAsync: jest.fn() } as never);
    const { context } = contextWithAuthorization();

    await expect(guard.canActivate(context as never)).rejects.toBeInstanceOf(
      UnauthorizedException,
    );
  });

  it('rejects invalid or expired token', async () => {
    const jwtService = {
      verifyAsync: jest.fn().mockRejectedValue(new Error('expired')),
    };
    const guard = new JwtAuthGuard(jwtService as never);
    const { context } = contextWithAuthorization('Bearer expired');

    await expect(guard.canActivate(context as never)).rejects.toBeInstanceOf(
      UnauthorizedException,
    );
  });
});

import {
  CanActivate,
  ExecutionContext,
  Injectable,
  UnauthorizedException,
} from '@nestjs/common';
import { JwtService } from '@nestjs/jwt';
import type { AuthenticatedRequest } from '../types/authenticated-request';

@Injectable()
export class JwtAuthGuard implements CanActivate {
  constructor(private readonly jwtService: JwtService) {}

  async canActivate(context: ExecutionContext): Promise<boolean> {
    const request = context.switchToHttp().getRequest<AuthenticatedRequest>();
    const authorization = request.headers.authorization;

    if (!authorization?.startsWith('Bearer ')) {
      throw new UnauthorizedException('Missing bearer token');
    }

    const token = authorization.slice('Bearer '.length);

    try {
      const payload = await this.jwtService.verifyAsync(token);
      request.user = {
        ...payload,
        activeCompanyId: payload.activeCompanyId ?? payload.companyId ?? null,
      };
      if (request.user.type && request.user.type !== 'access') {
        throw new UnauthorizedException('Invalid token type');
      }
      return true;
    } catch {
      throw new UnauthorizedException('Invalid or expired token');
    }
  }
}

import {
  HttpException,
  HttpStatus,
  Injectable,
  NestMiddleware,
} from '@nestjs/common';
import type { NextFunction, Request, Response } from 'express';
import IORedis from 'ioredis';
import { env } from '../../config/env';

const buckets = new Map<string, { count: number; resetAt: number }>();
let redis: IORedis | undefined;
let redisDisabled = false;

@Injectable()
export class RateLimitMiddleware implements NestMiddleware {
  async use(request: Request, response: Response, next: NextFunction) {
    const key = this.resolveKey(request);

    try {
      if (!redisDisabled) {
        const count = await this.incrementRedisBucket(key);
        this.setHeaders(response, count);
        if (count > env.rateLimitMaxRequests) {
          this.reject();
        }
        next();
        return;
      }
    } catch {
      redisDisabled = true;
    }

    const count = this.incrementMemoryBucket(key);
    this.setHeaders(response, count);
    if (count > env.rateLimitMaxRequests) {
      this.reject();
    }
    next();
  }

  private async incrementRedisBucket(key: string) {
    redis = redis ?? new IORedis(env.redisUrl, {
      lazyConnect: true,
      enableOfflineQueue: false,
      maxRetriesPerRequest: 1,
    });
    if (redis.status === 'wait') {
      await redis.connect();
    }

    const redisKey = `rate-limit:${key}`;
    const count = await redis.incr(redisKey);
    if (count === 1) {
      await redis.pexpire(redisKey, env.rateLimitWindowMs);
    }
    return count;
  }

  private incrementMemoryBucket(key: string) {
    const now = Date.now();
    const bucket = buckets.get(key);

    if (!bucket || bucket.resetAt <= now) {
      buckets.set(key, { count: 1, resetAt: now + env.rateLimitWindowMs });
      return 1;
    }

    bucket.count += 1;
    return bucket.count;
  }

  private setHeaders(response: Response, count: number) {
    response.setHeader('X-RateLimit-Limit', env.rateLimitMaxRequests);
    response.setHeader('X-RateLimit-Remaining', Math.max(0, env.rateLimitMaxRequests - count));
  }

  private reject(): never {
    throw new HttpException('Rate limit exceeded', HttpStatus.TOO_MANY_REQUESTS);
  }

  private resolveKey(request: Request) {
    return request.ip ?? request.socket.remoteAddress ?? 'unknown';
  }
}

import type { Request } from 'express';

export type AuthenticatedUser = {
  sub: string;
  email: string;
  role: string;
  companyId: string | null;

  // Empresa seleccionada por el SUPER_ADMIN
  activeCompanyId?: string | null;

  type?: string;
};

export type AuthenticatedRequest = Request & {
  user: AuthenticatedUser;
};

import { ValidationPipe } from '@nestjs/common';
import { NestFactory } from '@nestjs/core';
import { DocumentBuilder, SwaggerModule } from '@nestjs/swagger';
import { AppModule } from './app.module';
import { assertProductionEnv, env } from './config/env';

async function bootstrap() {
  assertProductionEnv();
  const app = await NestFactory.create(AppModule);

  app.setGlobalPrefix('api/v1');
  app.enableShutdownHooks();
  app.enableCors({
    origin: env.corsOrigins,
    credentials: true,
    methods: ['GET', 'POST', 'PATCH', 'DELETE', 'OPTIONS'],
    allowedHeaders: ['Content-Type', 'Authorization'],
  });
  app.useGlobalPipes(
    new ValidationPipe({
      whitelist: true,
      forbidNonWhitelisted: true,
      transform: true,
    }),
  );

  const swaggerConfig = new DocumentBuilder()
    .setTitle('SG-SST ERP API')
    .setDescription('API para gestion de empresas, empleados y procesos SG-SST.')
    .setVersion('1.0')
    .addBearerAuth()
    .build();
  const swaggerDocument = SwaggerModule.createDocument(app, swaggerConfig);
  SwaggerModule.setup('docs', app, swaggerDocument, {
    swaggerOptions: { persistAuthorization: true },
  });

  await app.listen(env.port);
}
bootstrap();

import { Controller, Get, Query, UseGuards } from '@nestjs/common';
import { Roles } from '../../common/decorators/roles.decorator';
import { ListQueryDto } from '../../common/dto/list-query.dto';
import { JwtAuthGuard } from '../../common/guards/jwt-auth.guard';
import { RolesGuard } from '../../common/guards/roles.guard';
import { CurrentUser } from '../../common/decorators/current-user.decorator';
import type { AuthenticatedUser } from '../../common/types/authenticated-request';
import { AuditService } from './audit.service';

@Controller('audit-logs')
@UseGuards(JwtAuthGuard, RolesGuard)
export class AuditController {
  constructor(private readonly auditService: AuditService) {}

  @Get()
  @Roles('ADMIN', 'AUDITOR')
  findAll(@CurrentUser() user: AuthenticatedUser, @Query() query: ListQueryDto) {
    return this.auditService.findAll(user, query);
  }
}

import { Injectable } from '@nestjs/common';
import { Prisma } from '@prisma/client';
import { ListQueryDto } from '../../common/dto/list-query.dto';
import type { AuthenticatedUser } from '../../common/types/authenticated-request';
import { resolveCompanyScope } from '../../common/pipes/company-scope';
import { PrismaService } from '../../database/prisma.service';

type AuditInput = {
  user?: AuthenticatedUser;
  action: string;
  entity: string;
  entityId?: string;
  before?: unknown;
  after?: unknown;
};

@Injectable()
export class AuditService {
  constructor(private readonly prisma: PrismaService) {}

  log(input: AuditInput) {
    return this.prisma.auditLog.create({
      data: {
        action: input.action,
        entity: input.entity,
        entityId: input.entityId,
        actorId: input.user?.sub,
        before: this.toJson(input.before),
        after: this.toJson(input.after),
      },
    });
  }

  async findAll(user: AuthenticatedUser, query: ListQueryDto) {
    const page = query.page ?? 1;
    const pageSize = query.pageSize ?? 10;
    const search = query.search?.trim();
    const where: Prisma.AuditLogWhereInput = {
      actor: { companyId: resolveCompanyScope(user) },
      ...(search
      ? {
          OR: [
            { action: { contains: search, mode: 'insensitive' } },
            { entity: { contains: search, mode: 'insensitive' } },
            { entityId: { contains: search, mode: 'insensitive' } },
            { actor: { email: { contains: search, mode: 'insensitive' } } },
            { actor: { name: { contains: search, mode: 'insensitive' } } },
          ],
        }
      : {}),
    };
    const [data, total] = await this.prisma.$transaction([
      this.prisma.auditLog.findMany({
        where,
        include: {
          actor: {
            select: {
              id: true,
              name: true,
              email: true,
              role: true,
            },
          },
        },
        orderBy: { createdAt: 'desc' },
        skip: (page - 1) * pageSize,
        take: pageSize,
      }),
      this.prisma.auditLog.count({ where }),
    ]);
    return {
      data,
      meta: { page, pageSize, total, totalPages: Math.ceil(total / pageSize) },
    };
  }

  private toJson(value: unknown): Prisma.InputJsonValue | undefined {
    if (value === undefined) {
      return undefined;
    }
    return JSON.parse(JSON.stringify(value)) as Prisma.InputJsonValue;
  }
}

import { Body, Controller, Get, Post, UseGuards } from '@nestjs/common';
import { CurrentUser } from '../../common/decorators/current-user.decorator';
import { JwtAuthGuard } from '../../common/guards/jwt-auth.guard';
import type { AuthenticatedUser } from '../../common/types/authenticated-request';
import { CreateUserDto } from '../users/dto/create-user.dto';
import { AuthService } from './auth.service';
import { ChangePasswordDto } from './dto/change-password.dto';
import { EnableMfaDto } from './dto/enable-mfa.dto';
import { LoginDto } from './dto/login.dto';
import { RefreshTokenDto } from './dto/refresh-token.dto';
import { RequestPasswordResetDto } from './dto/request-password-reset.dto';
import { ResetPasswordDto } from './dto/reset-password.dto';
import { SwitchActiveCompanyDto } from './dto/switch-active-company.dto';
import { VerifyMfaDto } from './dto/verify-mfa.dto';

@Controller('auth')
export class AuthController {
  constructor(private readonly authService: AuthService) {}

  @Post('login')
  login(@Body() dto: LoginDto) {
    return this.authService.login(dto);
  }

  @Post('refresh')
  refresh(@Body() dto: RefreshTokenDto) {
    return this.authService.refresh(dto);
  }

  @Post('verify-mfa')
  verifyMfa(@Body() dto: VerifyMfaDto) {
    return this.authService.verifyMfa(dto);
  }

  @Post('logout')
  @UseGuards(JwtAuthGuard)
  logout(@CurrentUser() user: AuthenticatedUser) {
    return this.authService.logout(user);
  }

  @Post('change-password')
  @UseGuards(JwtAuthGuard)
  changePassword(
    @CurrentUser() user: AuthenticatedUser,
    @Body() dto: ChangePasswordDto,
  ) {
    return this.authService.changePassword(user, dto);
  }

  @Post('active-company')
  @UseGuards(JwtAuthGuard)
  switchActiveCompany(
    @CurrentUser() user: AuthenticatedUser,
    @Body() dto: SwitchActiveCompanyDto,
  ) {
    return this.authService.switchActiveCompany(user, dto);
  }

  @Post('mfa/setup')
  @UseGuards(JwtAuthGuard)
  setupMfa(@CurrentUser() user: AuthenticatedUser) {
    return this.authService.setupMfa(user);
  }

  @Post('mfa/enable')
  @UseGuards(JwtAuthGuard)
  enableMfa(@CurrentUser() user: AuthenticatedUser, @Body() dto: EnableMfaDto) {
    return this.authService.enableMfa(user, dto);
  }

  @Post('mfa/disable')
  @UseGuards(JwtAuthGuard)
  disableMfa(@CurrentUser() user: AuthenticatedUser, @Body() dto: EnableMfaDto) {
    return this.authService.disableMfa(user, dto);
  }

  @Post('request-password-reset')
  requestPasswordReset(@Body() dto: RequestPasswordResetDto) {
    return this.authService.requestPasswordReset(dto);
  }

  @Post('reset-password')
  resetPassword(@Body() dto: ResetPasswordDto) {
    return this.authService.resetPassword(dto);
  }

  @Post('bootstrap-admin')
  bootstrapAdmin(@Body() dto: CreateUserDto) {
    return this.authService.bootstrapAdmin(dto);
  }

  @Get('me')
  @UseGuards(JwtAuthGuard)
  me(@CurrentUser() user: AuthenticatedUser) {
    return user;
  }
}

import { Global, Module } from '@nestjs/common';
import { JwtModule } from '@nestjs/jwt';
import { env } from '../../config/env';
import { UsersModule } from '../users/users.module';
import { AuthController } from './auth.controller';
import { AuthService } from './auth.service';
import { TotpService } from './totp.service';

@Global()
@Module({
  imports: [
    UsersModule,
    JwtModule.register({
  secret: env.jwtSecret,
  signOptions: {
    expiresIn: '1d',},
    }),
  ],
  controllers: [AuthController],
  providers: [AuthService, TotpService],
  exports: [AuthService, JwtModule],
})
export class AuthModule {}

import { ConflictException, UnauthorizedException } from '@nestjs/common';
import * as bcrypt from 'bcrypt';
import { AuthService } from './auth.service';

describe('AuthService', () => {
  const jwtService = {
    signAsync: jest.fn(),
  };
  const usersRepository = {
    findByEmail: jest.fn(),
    findAuthById: jest.fn(),
    count: jest.fn(),
    create: jest.fn(),
    updateRefreshTokenHash: jest.fn(),
    updatePassword: jest.fn(),
    updatePasswordResetToken: jest.fn(),
  };
  const totpService = {
    verify: jest.fn(),
    generateSecret: jest.fn(),
    otpauthUrl: jest.fn(),
  };
  const prisma = {
    company: {
      findFirst: jest.fn(),
    },
  };
  let service: AuthService;

  beforeEach(() => {
    jest.clearAllMocks();
    service = new AuthService(
      usersRepository as never,
      jwtService as never,
      totpService as never,
      prisma as never,
    );
  });

  it('logs in active users and signs JWT payload with role and company scope', async () => {
    const password = await bcrypt.hash('Admin12345', 12);
    usersRepository.findByEmail.mockResolvedValue({
      id: 'user-1',
      name: 'Admin',
      email: 'admin@sgsst.com',
      password,
      role: 'ADMIN',
      companyId: 'company-1',
      isActive: true,
    });
    jwtService.signAsync.mockResolvedValue('signed-token');

    const result = await service.login({
      email: 'admin@sgsst.com',
      password: 'Admin12345',
    });

    expect(jwtService.signAsync).toHaveBeenCalledWith({
      sub: 'user-1',
      email: 'admin@sgsst.com',
      role: 'ADMIN',
      companyId: 'company-1',
      activeCompanyId: 'company-1',
      type: 'access',
    });
    expect(result.accessToken).toBe('signed-token');
    expect(result.refreshToken).toBe('signed-token');
    expect(usersRepository.updateRefreshTokenHash).toHaveBeenCalledWith(
      'user-1',
      expect.any(String),
    );
    expect(result.user).toMatchObject({
      id: 'user-1',
      role: 'ADMIN',
      companyId: 'company-1',
      activeCompanyId: 'company-1',
    });
  });

  it('rejects inactive users even with a valid password', async () => {
    const password = await bcrypt.hash('Admin12345', 12);
    usersRepository.findByEmail.mockResolvedValue({
      password,
      isActive: false,
    });

    await expect(
      service.login({ email: 'inactive@sgsst.com', password: 'Admin12345' }),
    ).rejects.toBeInstanceOf(UnauthorizedException);
    expect(jwtService.signAsync).not.toHaveBeenCalled();
  });

  it('rejects invalid credentials', async () => {
    usersRepository.findByEmail.mockResolvedValue(null);

    await expect(
      service.login({ email: 'missing@sgsst.com', password: 'bad-pass' }),
    ).rejects.toBeInstanceOf(UnauthorizedException);
  });

  it('allows bootstrap admin only when there are no users', async () => {
    usersRepository.count.mockResolvedValue(1);

    await expect(
      service.bootstrapAdmin({
        name: 'Admin',
        email: 'admin@sgsst.com',
        password: 'Admin12345',
        role: 'ADMIN',
      }),
    ).rejects.toBeInstanceOf(ConflictException);
  });
});

import {
  ConflictException,
  Injectable,
  UnauthorizedException,
} from '@nestjs/common';
import { JwtService } from '@nestjs/jwt';
import { randomUUID } from 'node:crypto';
import * as bcrypt from 'bcrypt';
import { env } from '../../config/env';
import { PrismaService } from '../../database/prisma.service';
import { UsersRepository } from '../users/users.repository';
import { CreateUserDto } from '../users/dto/create-user.dto';
import type { AuthenticatedUser } from '../../common/types/authenticated-request';
import { ChangePasswordDto } from './dto/change-password.dto';
import { EnableMfaDto } from './dto/enable-mfa.dto';
import { LoginDto } from './dto/login.dto';
import { RefreshTokenDto } from './dto/refresh-token.dto';
import { RequestPasswordResetDto } from './dto/request-password-reset.dto';
import { ResetPasswordDto } from './dto/reset-password.dto';
import { SwitchActiveCompanyDto } from './dto/switch-active-company.dto';
import { VerifyMfaDto } from './dto/verify-mfa.dto';
import { TotpService } from './totp.service';

const criticalMfaRoles = new Set(['SUPER_ADMIN', 'ADMIN', 'SST', 'AUDITOR']);

@Injectable()
export class AuthService {
  constructor(
    private readonly usersRepository: UsersRepository,
    private readonly jwtService: JwtService,
    private readonly totpService: TotpService,
    private readonly prisma: PrismaService,
  ) {}

  async login(dto: LoginDto) {
    const user = await this.usersRepository.findByEmail(dto.email);

    if (
      !user ||
      !user.isActive ||
      !(await bcrypt.compare(dto.password, user.password))
    ) {
      throw new UnauthorizedException('Invalid credentials');
    }

    if (criticalMfaRoles.has(String(user.role)) && user.mfaEnabled) {
      return {
        mfaRequired: true,
        mfaToken: await this.jwtService.signAsync(
          { sub: user.id, type: 'mfa', jti: randomUUID() },
          { expiresIn: '5m' as never },
        ),
        tokenType: 'MFA',
      };
    }

    return this.issueSession(user);
  }

  async verifyMfa(dto: VerifyMfaDto) {
    const payload = await this.verifyToken(dto.mfaToken, 'mfa');
    const user = await this.usersRepository.findAuthById(payload.sub);
    if (!user || !user.isActive || !user.mfaEnabled || !user.mfaSecret) {
      throw new UnauthorizedException('Invalid MFA challenge');
    }
    if (!this.totpService.verify(user.mfaSecret, dto.code)) {
      throw new UnauthorizedException('Invalid MFA code');
    }
    return this.issueSession(user);
  }

  async refresh(dto: RefreshTokenDto) {
    const payload = await this.verifyToken(dto.refreshToken, 'refresh');
    const user = await this.usersRepository.findAuthById(payload.sub);
    if (!user || !user.isActive || !user.refreshTokenHash) {
      throw new UnauthorizedException('Invalid refresh token');
    }
    const valid = await bcrypt.compare(dto.refreshToken, user.refreshTokenHash);
    if (!valid) {
      throw new UnauthorizedException('Invalid refresh token');
    }
    return this.issueSession(user);
  }

  async logout(user: AuthenticatedUser) {
    await this.usersRepository.updateRefreshTokenHash(user.sub, null);
    return { success: true };
  }

  async switchActiveCompany(user: AuthenticatedUser, dto: SwitchActiveCompanyDto) {
    const existing = await this.usersRepository.findAuthById(user.sub);
    if (!existing || !existing.isActive) {
      throw new UnauthorizedException('Invalid user');
    }

    if (existing.role !== 'SUPER_ADMIN') {
      if (!dto.companyId || dto.companyId !== existing.companyId) {
        throw new UnauthorizedException('Invalid company scope');
      }
      return this.issueSession(existing, dto.companyId);
    }

    if (dto.companyId) {
      const company = await this.prisma.company.findFirst({
        where: { id: dto.companyId, isActive: true },
        select: { id: true },
      });
      if (!company) {
        throw new UnauthorizedException('Invalid company scope');
      }
    }

    return this.issueSession(existing, dto.companyId ?? null);
  }

  async changePassword(user: AuthenticatedUser, dto: ChangePasswordDto) {
    const existing = await this.usersRepository.findAuthById(user.sub);
    if (
      !existing ||
      !existing.isActive ||
      !(await bcrypt.compare(dto.currentPassword, existing.password))
    ) {
      throw new UnauthorizedException('Invalid current password');
    }
    const passwordHash = await bcrypt.hash(dto.newPassword, 12);
    await this.usersRepository.updatePassword(user.sub, passwordHash);
    return { success: true };
  }

  async setupMfa(user: AuthenticatedUser) {
    const existing = await this.usersRepository.findAuthById(user.sub);
    if (!existing || !existing.isActive) {
      throw new UnauthorizedException('Invalid user');
    }
    const secret = existing.mfaSecret ?? this.totpService.generateSecret();
    await this.usersRepository.updateMfaSecret(existing.id, secret, existing.mfaEnabled);
    return {
      secret,
      otpauthUrl: this.totpService.otpauthUrl(existing.email, secret),
      enabled: existing.mfaEnabled,
    };
  }

  async enableMfa(user: AuthenticatedUser, dto: EnableMfaDto) {
    const existing = await this.usersRepository.findAuthById(user.sub);
    if (!existing || !existing.isActive || !existing.mfaSecret) {
      throw new UnauthorizedException('MFA setup is required');
    }
    if (!this.totpService.verify(existing.mfaSecret, dto.code)) {
      throw new UnauthorizedException('Invalid MFA code');
    }
    await this.usersRepository.updateMfaSecret(existing.id, existing.mfaSecret, true);
    return { success: true };
  }

  async disableMfa(user: AuthenticatedUser, dto: EnableMfaDto) {
    const existing = await this.usersRepository.findAuthById(user.sub);
    if (!existing || !existing.isActive || !existing.mfaSecret) {
      throw new UnauthorizedException('Invalid user');
    }
    if (!this.totpService.verify(existing.mfaSecret, dto.code)) {
      throw new UnauthorizedException('Invalid MFA code');
    }
    await this.usersRepository.updateMfaSecret(existing.id, null, false);
    return { success: true };
  }

  async requestPasswordReset(dto: RequestPasswordResetDto) {
    const user = await this.usersRepository.findByEmail(dto.email);
    if (!user || !user.isActive) {
      return { success: true };
    }

    const resetToken = await this.jwtService.signAsync(
      { sub: user.id, type: 'password-reset', jti: randomUUID() },
      { expiresIn: `${env.passwordResetExpiresMinutes}m` as never },
    );
    const resetTokenHash = await bcrypt.hash(resetToken, 12);
    const expiresAt = new Date(Date.now() + env.passwordResetExpiresMinutes * 60_000);
    await this.usersRepository.updatePasswordResetToken(
      user.id,
      resetTokenHash,
      expiresAt,
    );

    return {
      success: true,
      ...(env.nodeEnv === 'production' ? {} : { resetToken }),
    };
  }

  async resetPassword(dto: ResetPasswordDto) {
    const payload = await this.verifyToken(dto.resetToken, 'password-reset');
    const user = await this.usersRepository.findAuthById(payload.sub);
    if (
      !user ||
      !user.isActive ||
      !user.passwordResetTokenHash ||
      !user.passwordResetExpiresAt ||
      user.passwordResetExpiresAt.getTime() < Date.now() ||
      !(await bcrypt.compare(dto.resetToken, user.passwordResetTokenHash))
    ) {
      throw new UnauthorizedException('Invalid or expired reset token');
    }

    const passwordHash = await bcrypt.hash(dto.newPassword, 12);
    await this.usersRepository.updatePassword(user.id, passwordHash);
    return { success: true };
  }

  async bootstrapAdmin(dto: CreateUserDto) {
    const usersCount = await this.usersRepository.count();
    if (usersCount > 0) {
      throw new ConflictException('Initial administrator already exists');
    }

    const passwordHash = await bcrypt.hash(dto.password, 12);
    return this.usersRepository.create(
      { ...dto, role: 'SUPER_ADMIN', companyId: undefined },
      passwordHash,
    );
  }

  private async issueSession(user: {
    id: string;
    name: string;
    email: string;
    role: string;
    companyId?: string | null;
    mfaEnabled?: boolean;
  }, activeCompanyId = user.companyId ?? null) {
    const payload = this.toAccessPayload(user, activeCompanyId);
    const refreshToken = await this.jwtService.signAsync(
      { sub: user.id, type: 'refresh', jti: randomUUID() },
      { expiresIn: env.refreshTokenExpiresIn as never },
    );
    await this.usersRepository.updateRefreshTokenHash(
      user.id,
      await bcrypt.hash(refreshToken, 12),
    );

    return {
      accessToken: await this.jwtService.signAsync(payload),
      refreshToken,
      tokenType: 'Bearer',
      expiresIn: env.jwtExpiresIn,
      user: {
        id: user.id,
        name: user.name,
        email: user.email,
        role: user.role,
        companyId: user.companyId,
        activeCompanyId,
        mfaEnabled: user.mfaEnabled,
      },
    };
  }

  private toAccessPayload(user: {
    id: string;
    email: string;
    role: string;
    companyId?: string | null;
  }, activeCompanyId: string | null) {
    return {
      sub: user.id,
      email: user.email,
      role: user.role,
      companyId: user.companyId,
      activeCompanyId,
      type: 'access',
    };
  }

  private async verifyToken(token: string, expectedType: string) {
    try {
      const payload = await this.jwtService.verifyAsync(token);
      if (payload.type !== expectedType || !payload.sub) {
        throw new UnauthorizedException('Invalid token');
      }
      return payload as { sub: string; type: string };
    } catch {
      throw new UnauthorizedException('Invalid or expired token');
    }
  }
}

import { Injectable } from '@nestjs/common';
import { createHmac, randomBytes } from 'node:crypto';

const alphabet = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ234567';

@Injectable()
export class TotpService {
  generateSecret() {
    const bytes = randomBytes(20);
    let bits = '';
    let output = '';
    for (const byte of bytes) {
      bits += byte.toString(2).padStart(8, '0');
      while (bits.length >= 5) {
        output += alphabet[parseInt(bits.slice(0, 5), 2)];
        bits = bits.slice(5);
      }
    }
    if (bits.length > 0) {
      output += alphabet[parseInt(bits.padEnd(5, '0'), 2)];
    }
    return output;
  }

  verify(secret: string, code: string) {
    const normalized = code.replace(/\s/g, '');
    if (!/^\d{6}$/.test(normalized)) {
      return false;
    }
    const step = Math.floor(Date.now() / 30_000);
    return [-1, 0, 1].some((offset) => this.generateCode(secret, step + offset) === normalized);
  }

  otpauthUrl(email: string, secret: string) {
    const issuer = 'SG-SST ERP';
    return `otpauth://totp/${encodeURIComponent(issuer)}:${encodeURIComponent(email)}?secret=${secret}&issuer=${encodeURIComponent(issuer)}&algorithm=SHA1&digits=6&period=30`;
  }

  private generateCode(secret: string, step: number) {
    const counter = Buffer.alloc(8);
    counter.writeBigUInt64BE(BigInt(step));
    const hmac = createHmac('sha1', this.decodeBase32(secret)).update(counter).digest();
    const offset = hmac[hmac.length - 1] & 0xf;
    const binary =
      ((hmac[offset] & 0x7f) << 24) |
      ((hmac[offset + 1] & 0xff) << 16) |
      ((hmac[offset + 2] & 0xff) << 8) |
      (hmac[offset + 3] & 0xff);
    return String(binary % 1_000_000).padStart(6, '0');
  }

  private decodeBase32(secret: string) {
    const clean = secret.replace(/=+$/, '').replace(/\s/g, '').toUpperCase();
    let bits = '';
    const bytes: number[] = [];
    for (const char of clean) {
      const value = alphabet.indexOf(char);
      if (value < 0) continue;
      bits += value.toString(2).padStart(5, '0');
      while (bits.length >= 8) {
        bytes.push(parseInt(bits.slice(0, 8), 2));
        bits = bits.slice(8);
      }
    }
    return Buffer.from(bytes);
  }
}

