import { EmailService } from './email.service';
import { WhatsAppDeliveryError, WhatsAppService } from './whatsapp.service';

type NotificationInput = {
  userId: string;
  companyId?: string | null;
  title: string;
  message: string;
  type?: NotificationType;
  priority?: NotificationPriority;
  entity?: string;
  entityId?: string;
};

@Injectable()
export class NotificationsService {
  private readonly logger = new Logger(NotificationsService.name);

  constructor(
    private readonly prisma: PrismaService,
    private readonly emailService: EmailService,
    private readonly whatsAppService: WhatsAppService,
  ) {}

  async findForUser(user: AuthenticatedUser, query: ListQueryDto) {
    const page = query.page ?? 1;
    const pageSize = query.pageSize ?? 10;
    const search = query.search?.trim();
    const where: Prisma.NotificationWhereInput = {
      userId: user.sub,
      read: query.isActive === undefined ? undefined : !query.isActive,
      ...(search
        ? {
            OR: [
              { title: { contains: search, mode: 'insensitive' } },
              { message: { contains: search, mode: 'insensitive' } },
              { entity: { contains: search, mode: 'insensitive' } },
            ],
          }
        : {}),
    };

    const [data, total, unread] = await this.prisma.$transaction([
      this.prisma.notification.findMany({
        where,
        orderBy: { createdAt: 'desc' },
        skip: (page - 1) * pageSize,
        take: pageSize,
      }),
      this.prisma.notification.count({ where }),
      this.prisma.notification.count({
        where: { userId: user.sub, read: false },
      }),
    ]);

    return {
      data,
      meta: {
        page,
        pageSize,
        total,
        totalPages: Math.ceil(total / pageSize),
        unread,
      },
    };
  }

  async markRead(user: AuthenticatedUser, id: string) {
    // Solo el dueño marca como leída; actores con empresa activa no leen notificaciones
    // ajenas aunque compartan empresa (las notificaciones son personales).
    const notification = await this.prisma.notification.findFirst({
      where: { id, userId: user.sub },
    });
    if (!notification) {
      throw new NotFoundException('Notification not found');
    }
    return this.prisma.notification.update({
      where: { id },
      data: { read: true, readAt: new Date() },
    });
  }

  async markAllRead(user: AuthenticatedUser) {
    await this.prisma.notification.updateMany({
      where: { userId: user.sub, read: false },
      data: { read: true, readAt: new Date() },
    });
    return { success: true };
  }

  async create(input: NotificationInput) {
    const existing = input.entityId
      ? await this.prisma.notification.findFirst({
          where: {
            userId: input.userId,
            type: input.type ?? NotificationType.INFO,
            entity: input.entity,
            entityId: input.entityId,
            read: false,
          },
        })
      : null;
    if (existing) {
      return existing;
    }

    const notification = await this.prisma.notification.create({
      data: {
        userId: input.userId,
        companyId: input.companyId,
        title: input.title,
        message: input.message,
        type: input.type ?? NotificationType.INFO,
        priority: input.priority ?? NotificationPriority.MEDIUM,
        entity: input.entity,
        entityId: input.entityId,
      },
      include: {
        user: { select: { email: true, name: true } },
      },
    });
    void this.sendNotificationEmail(notification).catch((error: unknown) => {
      this.logger.warn(`Notification email failed: ${String(error)}`);
    });
    return notification;
  }

  async sendCompanyWhatsAppAlert(input: {
    companyId?: string | null;
    title: string;
    message: string;
    priority: NotificationPriority;
    entity?: string;
    entityId?: string;
  }) {
    if (
      !input.companyId ||
      (input.priority !== NotificationPriority.HIGH &&
        input.priority !== NotificationPriority.CRITICAL)
    ) {
      return this.createExternalDelivery({
        provider: ExternalDeliveryProvider.WHATSAPP,
        status: ExternalDeliveryStatus.SKIPPED,
        companyId: input.companyId,
        subject: input.title,
        error:
          'Alert is not company-scoped or priority does not require WhatsApp',
        entity: input.entity,
        entityId: input.entityId,
      });
    }

    const company = await this.prisma.company.findUnique({
      where: { id: input.companyId },
      select: {
        name: true,
        whatsappAlertsEnabled: true,
        whatsappAlertPhone: true,
      },
    });
    if (!company?.whatsappAlertsEnabled || !company.whatsappAlertPhone) {
      return this.createExternalDelivery({
        provider: ExternalDeliveryProvider.WHATSAPP,
        status: ExternalDeliveryStatus.SKIPPED,
        companyId: input.companyId,
        subject: input.title,
        target: company?.whatsappAlertPhone,
        error: 'WhatsApp alerts are disabled or phone is missing for company',
        entity: input.entity,
        entityId: input.entityId,
      });
    }

    const text = [
      `SG-SST ERP - ${input.title}`,
      `Empresa: ${company.name}`,
      `Prioridad: ${input.priority}`,
      input.message,
    ].join('\n');
    const delivery = await this.createExternalDelivery({
      provider: ExternalDeliveryProvider.WHATSAPP,
      status: ExternalDeliveryStatus.PENDING,
      companyId: input.companyId,
      target: company.whatsappAlertPhone,
      subject: input.title,
      payload: { text, priority: input.priority },
      entity: input.entity,
      entityId: input.entityId,
    });

    try {
      const result = await this.whatsAppService.sendText({
        to: company.whatsappAlertPhone,
        text,
      });
      if (!result.sent) {
        return this.updateExternalDelivery(delivery.id, {
          status: ExternalDeliveryStatus.SKIPPED,
          response: result as Prisma.InputJsonObject,
          error: result.disabled
            ? 'WhatsApp channel is globally disabled'
            : 'WhatsApp channel is misconfigured',
        });
      }

      return this.updateExternalDelivery(delivery.id, {
        status: ExternalDeliveryStatus.SENT,
        response: result.response as Prisma.InputJsonValue,
        deliveredAt: new Date(),
      });
    } catch (error) {
      const deliveryError =
        error instanceof WhatsAppDeliveryError ? error : null;
      const attemptCount = 1;
      return this.updateExternalDelivery(delivery.id, {
        status: ExternalDeliveryStatus.FAILED,
        response: deliveryError?.response as Prisma.InputJsonValue,
        error: error instanceof Error ? error.message : String(error),
        attemptCount,
        nextAttemptAt:
          attemptCount >= env.externalDeliveryMaxAttempts
            ? null
            : this.nextRetryDate(attemptCount),
      });
    }
  }

  private createExternalDelivery(data: {
    provider: ExternalDeliveryProvider;
    status: ExternalDeliveryStatus;
    companyId?: string | null;
    target?: string | null;
    subject?: string;
    payload?: Prisma.InputJsonValue;
    response?: Prisma.InputJsonValue;
    error?: string;
    entity?: string;
    entityId?: string;
  }) {
    return this.prisma.externalDelivery.create({
      data: {
        provider: data.provider,
        status: data.status,
        maxAttempts: Math.max(env.externalDeliveryMaxAttempts, 1),
        companyId: data.companyId,
        target: data.target,
        subject: data.subject,
        payload: data.payload,
        response: data.response,
        error: data.error,
        entity: data.entity,
        entityId: data.entityId,
        deliveredAt:
          data.status === ExternalDeliveryStatus.SENT ? new Date() : undefined,
      },
    });
  }

  private updateExternalDelivery(
    id: string,
    data: {
      status: ExternalDeliveryStatus;
      response?: Prisma.InputJsonValue;
      error?: string | null;
      deliveredAt?: Date;
      attemptCount?: number;
      nextAttemptAt?: Date | null;
    },
  ) {
    return this.prisma.externalDelivery.update({
      where: { id },
      data,
    });
  }

  async retryFailedExternalDeliveries(limit = 25, companyId?: string) {
    const now = new Date();
    const deliveries = await this.prisma.externalDelivery.findMany({
      where: {
        status: ExternalDeliveryStatus.FAILED,
        ...(companyId ? { companyId } : {}),
        attemptCount: { lt: env.externalDeliveryMaxAttempts },
        OR: [{ nextAttemptAt: null }, { nextAttemptAt: { lte: now } }],
      },
      orderBy: { attemptedAt: 'asc' },
      take: limit,
    });

    let retried = 0;
    let sent = 0;
    let failed = 0;
    let skipped = 0;
    for (const delivery of deliveries) {
      retried += 1;
      const result = await this.retryExternalDelivery(delivery.id);
      if (result.status === ExternalDeliveryStatus.SENT) sent += 1;
      if (result.status === ExternalDeliveryStatus.FAILED) failed += 1;
      if (result.status === ExternalDeliveryStatus.SKIPPED) skipped += 1;
    }

    return {
      success: true,
      scanned: deliveries.length,
      retried,
      sent,
      failed,
      skipped,
    };
  }

  async findExternalDeliveries(
    user: AuthenticatedUser,
    query: ExternalDeliveriesQueryDto,
  ) {
    const page = query.page ?? 1;
    const pageSize = query.pageSize ?? 10;
    const search = query.search?.trim();
    const where: Prisma.ExternalDeliveryWhereInput = {
      provider: query.provider as ExternalDeliveryProvider | undefined,
      status: query.status as ExternalDeliveryStatus | undefined,
      companyId: resolveCompanyScope(user, query.companyId),
      ...(search
        ? {
            OR: [
              { target: { contains: search, mode: 'insensitive' } },
              { subject: { contains: search, mode: 'insensitive' } },
              { error: { contains: search, mode: 'insensitive' } },
              { entity: { contains: search, mode: 'insensitive' } },
              { entityId: { contains: search, mode: 'insensitive' } },
            ],
          }
        : {}),
    };
    const [data, total] = await this.prisma.$transaction([
      this.prisma.externalDelivery.findMany({
        where,
        include: { company: { select: { id: true, name: true, nit: true } } },
        orderBy: { attemptedAt: 'desc' },
        skip: (page - 1) * pageSize,
        take: pageSize,
      }),
      this.prisma.externalDelivery.count({ where }),
    ]);
    return {
      data,
      meta: { page, pageSize, total, totalPages: Math.ceil(total / pageSize) },
    };
  }

  async retryExternalDelivery(id: string, options?: { force?: boolean }) {
    const delivery = await this.prisma.externalDelivery.findUnique({
      where: { id },
    });
    if (!delivery) {
      throw new NotFoundException('External delivery not found');
    }
    if (
      !options?.force &&
      (delivery.status !== ExternalDeliveryStatus.FAILED ||
        (delivery.nextAttemptAt && delivery.nextAttemptAt > new Date()))
    ) {
      return delivery;
    }
    if (delivery.provider !== ExternalDeliveryProvider.WHATSAPP) {
      return this.updateExternalDelivery(delivery.id, {
        status: ExternalDeliveryStatus.SKIPPED,
        error: `Retry not implemented for provider ${delivery.provider}`,
      });
    }
    if (!delivery.target || !this.isTextPayload(delivery.payload)) {
      return this.updateExternalDelivery(delivery.id, {
        status: ExternalDeliveryStatus.SKIPPED,
        error: 'WhatsApp retry requires target and text payload',
      });
    }

    const attemptCount = delivery.attemptCount + 1;
    await this.prisma.externalDelivery.update({
      where: { id: delivery.id },
      data: {
        status: ExternalDeliveryStatus.PENDING,
        attemptCount,
        attemptedAt: new Date(),
        nextAttemptAt: null,
      },
    });

    try {
      const result = await this.whatsAppService.sendText({
        to: delivery.target,
        text: delivery.payload.text,
      });
      if (!result.sent) {
        return this.updateExternalDelivery(delivery.id, {
          status: ExternalDeliveryStatus.SKIPPED,
          response: result as Prisma.InputJsonObject,
          error: result.disabled
            ? 'WhatsApp channel is globally disabled'
            : 'WhatsApp channel is misconfigured',
        });
      }

      return this.updateExternalDelivery(delivery.id, {
        status: ExternalDeliveryStatus.SENT,
        response: result.response as Prisma.InputJsonValue,
        error: null,
        deliveredAt: new Date(),
        nextAttemptAt: null,
      });
    } catch (error) {
      const nextAttemptAt =
        attemptCount >= delivery.maxAttempts
          ? null
          : this.nextRetryDate(attemptCount);
      const deliveryError =
        error instanceof WhatsAppDeliveryError ? error : null;
      return this.updateExternalDelivery(delivery.id, {
        status: ExternalDeliveryStatus.FAILED,
        response: deliveryError?.response as Prisma.InputJsonValue,
        error: error instanceof Error ? error.message : String(error),
        nextAttemptAt,
      });
    }
  }

  async retryExternalDeliveryForUser(user: AuthenticatedUser, id: string) {
    const delivery = await this.prisma.externalDelivery.findUnique({
      where: { id },
    });
    if (!delivery) {
      throw new NotFoundException('External delivery not found');
    }
    assertCompanyScope(user, delivery.companyId);
    return this.retryExternalDelivery(id, { force: true });
  }

  private nextRetryDate(attemptCount: number) {
    const seconds =
      env.externalDeliveryRetryBaseSeconds *
      Math.max(1, 2 ** (attemptCount - 1));
    return new Date(Date.now() + seconds * 1000);
  }

  private isTextPayload(
    payload: Prisma.JsonValue,
  ): payload is { text: string } {
    return Boolean(
      payload &&
      typeof payload === 'object' &&
      !Array.isArray(payload) &&
      'text' in payload &&
      typeof payload.text === 'string',
    );
  }

  async generateDueAlerts(user: AuthenticatedUser) {
    return this.generateDueAlertsForCompany(resolveCompanyScope(user));
  }

  async generateDueAlertsForAllCompanies() {
    const companies = await this.prisma.company.findMany({
      where: { isActive: true },
      select: { id: true },
    });
    const results = await Promise.all(
      companies.map((company) => this.generateDueAlertsForCompany(company.id)),
    );
    return {
      success: true,
      companies: companies.length,
      created: results.reduce((total, result) => total + result.created, 0),
    };
  }

  async generateDueAlertsForCompany(companyId: string) {
    const targetUsers = await this.prisma.user.findMany({
      where: {
        isActive: true,
        role: { in: [Role.ADMIN, Role.SST] },
        companyId,
      },
      select: { id: true, companyId: true, role: true },
    });

    const now = new Date();
    const next30Days = new Date(now.getTime() + 30 * 24 * 60 * 60 * 1000);
    const companyScope = { companyId };

    const [documents, trainings, incidents] = await this.prisma.$transaction([
      this.prisma.document.findMany({
        where: {
          ...companyScope,
          isActive: true,
          expiresAt: { gte: now, lte: next30Days },
        },
        select: { id: true, name: true, expiresAt: true, companyId: true },
      }),
      this.prisma.training.findMany({
        where: { ...companyScope, date: { lt: now } },
        select: { id: true, title: true, date: true, companyId: true },
      }),
      this.prisma.incident.findMany({
        where: {
          ...companyScope,
          status: { not: IncidentStatus.RESOLVED },
        },
        select: { id: true, title: true, status: true, companyId: true },
      }),
    ]);

    let created = 0;
    for (const targetUser of targetUsers) {
      const visibleDocuments = documents.filter((item) =>
        this.isVisibleForUser(targetUser, item.companyId),
      );
      const visibleTrainings = trainings.filter((item) =>
        this.isVisibleForUser(targetUser, item.companyId),
      );
      const visibleIncidents = incidents.filter((item) =>
        this.isVisibleForUser(targetUser, item.companyId),
      );

      for (const document of visibleDocuments) {
        const notification = await this.create({
          userId: targetUser.id,
          companyId: document.companyId,
          title: 'Documento proximo a vencer',
          message: `${document.name} vence el ${document.expiresAt?.toISOString().slice(0, 10)}`,
          type: NotificationType.DOCUMENT_EXPIRING,
          priority: NotificationPriority.HIGH,
          entity: 'Document',
          entityId: document.id,
        });
        if (notification.createdAt.getTime() >= now.getTime()) created += 1;
      }

      for (const training of visibleTrainings) {
        const notification = await this.create({
          userId: targetUser.id,
          companyId: training.companyId,
          title: 'Capacitacion vencida',
          message: `${training.title} estaba programada para ${training.date.toISOString().slice(0, 10)}`,
          type: NotificationType.TRAINING_OVERDUE,
          priority: NotificationPriority.MEDIUM,
          entity: 'Training',
          entityId: training.id,
        });
        if (notification.createdAt.getTime() >= now.getTime()) created += 1;
      }

      for (const incident of visibleIncidents) {
        const notification = await this.create({
          userId: targetUser.id,
          companyId: incident.companyId,
          title: 'Incidente abierto',
          message: `${incident.title} continua en estado ${incident.status}`,
          type: NotificationType.INCIDENT_OPEN,
          priority: NotificationPriority.CRITICAL,
          entity: 'Incident',
          entityId: incident.id,
        });
        if (notification.createdAt.getTime() >= now.getTime()) created += 1;
      }
    }

    return {
      success: true,
      created,
      scanned: {
        documents: documents.length,
        trainings: trainings.length,
        incidents: incidents.length,
      },
    };
  }

  private isVisibleForUser(
    user: { role: Role; companyId: string | null },
    companyId: string,
  ) {
    return user.role === Role.SUPER_ADMIN || user.companyId === companyId;
  }

  private async sendNotificationEmail(notification: {
    title: string;
    message: string;
    priority: NotificationPriority;
    user: { email: string; name: string };
  }) {
    if (
      notification.priority !== NotificationPriority.HIGH &&
      notification.priority !== NotificationPriority.CRITICAL
    ) {
      return;
    }

    await this.emailService.send({
      to: notification.user.email,
      subject: `[SG-SST] ${notification.title}`,
      text: `Hola ${notification.user.name},\n\n${notification.message}\n\nPrioridad: ${notification.priority}\n\nSG-SST ERP`,
      html: `<p>Hola ${notification.user.name},</p><p>${notification.message}</p><p><strong>Prioridad:</strong> ${notification.priority}</p><p>SG-SST ERP</p>`,
    });
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { env } from '../../config/env';

type WhatsAppInput = {
  to: string;
  text: string;
};

export class WhatsAppDeliveryError extends Error {
  constructor(
    message: string,
    readonly response?: unknown,
  ) {
    super(message);
  }
}

@Injectable()
export class WhatsAppService {
  private readonly logger = new Logger(WhatsAppService.name);

  async sendText(input: WhatsAppInput) {
    if (!env.whatsappEnabled) {
      this.logger.log(`[whatsapp disabled] ${input.to}`);
      return { sent: false, disabled: true };
    }

    if (!env.whatsappPhoneNumberId || !env.whatsappAccessToken) {
      this.logger.warn('WhatsApp is enabled but WHATSAPP_PHONE_NUMBER_ID or WHATSAPP_ACCESS_TOKEN is missing');
      return { sent: false, misconfigured: true };
    }

    const response = await fetch(
      `https://graph.facebook.com/${env.whatsappApiVersion}/${env.whatsappPhoneNumberId}/messages`,
      {
        method: 'POST',
        headers: {
          Authorization: `Bearer ${env.whatsappAccessToken}`,
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          messaging_product: 'whatsapp',
          recipient_type: 'individual',
          to: input.to.replace(/^\+/, ''),
          type: 'text',
          text: {
            preview_url: false,
            body: input.text,
          },
        }),
      },
    );

    if (!response.ok) {
      const body = await this.parseResponse(response);
      throw new WhatsAppDeliveryError(`WhatsApp API failed with ${response.status}`, body);
    }

    return { sent: true, response: await this.parseResponse(response) };
  }

  private async parseResponse(response: Response) {
    const text = await response.text();
    if (!text) return {};
    try {
      return JSON.parse(text) as unknown;
    } catch {
      return { body: text.slice(0, 1000) };
    }
  }
}

import { Injectable, Logger, OnModuleDestroy, OnModuleInit } from '@nestjs/common';
import { NotificationPriority, NotificationType } from '@prisma/client';
import { Job, Queue, Worker } from 'bullmq';
import IORedis from 'ioredis';
import type { AuthenticatedUser } from '../../common/types/authenticated-request';
import { env } from '../../config/env';
import { DocumentsStorageService } from '../documents/documents-storage.service';
import { NotificationsService } from '../notifications/notifications.service';
import type { ReportFormat } from './reports.service';
import { ReportsService } from './reports.service';

const QUEUE_NAME = 'sgsst-reports';
const GENERATE_REPORT_JOB = 'generate-report';
const CLEANUP_REPORTS_JOB = 'cleanup-expired-reports';
const CAPTURE_METRICS_JOB = 'capture-report-metrics';
const EVALUATE_ALERTS_JOB = 'evaluate-report-alerts';

type ReportJobData = {
  user: AuthenticatedUser;
  kind: string;
  format: ReportFormat;
  companyId?: string;
  exportId?: string;
};

@Injectable()
export class ReportsQueueService implements OnModuleInit, OnModuleDestroy {
  private readonly logger = new Logger(ReportsQueueService.name);
  private connection?: IORedis;
  private queue?: Queue;
  private worker?: Worker;

  constructor(
    private readonly reportsService: ReportsService,
    private readonly storageService: DocumentsStorageService,
    private readonly notificationsService: NotificationsService,
  ) {}

  async onModuleInit() {
    if (!env.reportsQueueEnabled) {
      this.logger.log('Reports queue disabled');
      return;
    }

    this.connection = new IORedis(env.redisUrl, { maxRetriesPerRequest: null });
    this.queue = new Queue(QUEUE_NAME, { connection: this.connection });
    if (!env.reportsWorkerEnabled) {
      this.logger.log('Reports worker disabled in this process');
      return;
    }

    this.worker = new Worker(QUEUE_NAME, (job) => this.process(job), {
      connection: this.connection,
    });
    this.worker.on('failed', (job, error) => {
      this.logger.error(`Report job failed: ${job?.id ?? 'unknown'}`, error.stack);
    });
    await this.scheduleMaintenance();
  }

  async enqueue(input: ReportJobData) {
    const reportExport = input.exportId
      ? await this.reportsService.markExportQueued(input.exportId)
      : await this.reportsService.createExport(input);
    const companyId = reportExport.companyId ?? undefined;
    const jobData: ReportJobData = {
      ...input,
      companyId,
      exportId: reportExport.id,
      user: {
        ...input.user,
        companyId: companyId ?? null,
        activeCompanyId: companyId ?? null,
      },
    };

    if (!this.queue) {
      const result = await this.generate(jobData);
      return { success: true, queued: false, exportId: reportExport.id, fileUrl: result.fileUrl };
    }

    const job = await this.queue.add(GENERATE_REPORT_JOB, jobData, {
      removeOnComplete: 50,
      removeOnFail: 100,
    });
    await this.reportsService.markExportQueued(reportExport.id, job.id);
    await this.reportsService.logScheduledExport({
      user: input.user,
      kind: input.kind,
      format: input.format,
      requestedCompanyId: input.companyId,
      status: 'QUEUED',
      jobId: job.id,
    });
    return { success: true, queued: true, exportId: reportExport.id, jobId: job.id };
  }

  async onModuleDestroy() {
    await this.worker?.close();
    await this.queue?.close();
    await this.connection?.quit();
  }

  private async process(job: Job) {
    if (job.name === CLEANUP_REPORTS_JOB) {
      return this.cleanupExpiredReports();
    }
    if (job.name === CAPTURE_METRICS_JOB) {
      return this.captureMetricSnapshots();
    }
    if (job.name === EVALUATE_ALERTS_JOB) {
      return this.evaluateMetricAlerts();
    }
    if (job.name === GENERATE_REPORT_JOB) {
      return this.generate(job.data as ReportJobData, job.id);
    }
    this.logger.warn(`Unknown report job: ${job.name}`);
    return { ignored: true };
  }

  private async scheduleMaintenance() {
    if (!this.queue) return;
    await this.queue.upsertJobScheduler(
      `${CLEANUP_REPORTS_JOB}-daily`,
      { pattern: env.reportsCleanupCron },
      {
        name: CLEANUP_REPORTS_JOB,
        data: {},
        opts: {
          removeOnComplete: 50,
          removeOnFail: 100,
        },
      },
    );
    this.logger.log(`Scheduled report cleanup job with cron: ${env.reportsCleanupCron}`);
    await this.queue.upsertJobScheduler(
      `${CAPTURE_METRICS_JOB}-daily`,
      { pattern: env.reportsMetricsCron },
      {
        name: CAPTURE_METRICS_JOB,
        data: {},
        opts: {
          removeOnComplete: 50,
          removeOnFail: 100,
        },
      },
    );
    this.logger.log(`Scheduled report metrics job with cron: ${env.reportsMetricsCron}`);
    await this.queue.upsertJobScheduler(
      `${EVALUATE_ALERTS_JOB}-daily`,
      { pattern: env.reportsAlertsCron },
      {
        name: EVALUATE_ALERTS_JOB,
        data: {},
        opts: {
          removeOnComplete: 50,
          removeOnFail: 100,
        },
      },
    );
    this.logger.log(`Scheduled report alerts job with cron: ${env.reportsAlertsCron}`);
  }

  private cleanupExpiredReports() {
    return this.reportsService.cleanupExpiredExports((storageKey) =>
      this.storageService.delete(storageKey),
    );
  }

  private captureMetricSnapshots() {
    return this.reportsService.captureDailyMetricSnapshots();
  }

  private async evaluateMetricAlerts() {
    const alerts = await this.reportsService.metricAlertCandidates();
    let notifications = 0;
    for (const alert of alerts) {
      const targets = await this.reportsService.metricAlertTargets(alert.companyId);
      const priority = alert.kind === 'FAILURE_RATE' ? NotificationPriority.CRITICAL : NotificationPriority.HIGH;
      for (const target of targets) {
        const notification = await this.notificationsService.create({
          userId: target.id,
          companyId: alert.companyId,
          title: alert.title,
          message: alert.message,
          type: NotificationType.INFO,
          priority,
          entity: 'ReportExportMetricSnapshot',
          entityId: `${alert.snapshotId}:${alert.kind}`,
        });
        if (notification.createdAt.getTime() >= Date.now() - 60_000) {
          notifications += 1;
        }
      }
      await this.notificationsService
        .sendCompanyWhatsAppAlert({
          companyId: alert.companyId,
          title: alert.title,
          message: alert.message,
          priority,
          entity: 'ReportExportMetricSnapshot',
          entityId: `${alert.snapshotId}:${alert.kind}`,
        })
        .catch((error: unknown) => {
          this.logger.warn(`WhatsApp report alert failed: ${String(error)}`);
        });
    }
    const date = new Date();
    date.setUTCDate(date.getUTCDate() - 1);
    await this.reportsService.logMetricAlertEvaluation({
      date: date.toISOString().slice(0, 10),
      alerts: alerts.length,
      notifications,
    });
    return { success: true, alerts: alerts.length, notifications };
  }

  private async generate(input: ReportJobData, jobId?: string) {
    let verifiedInput: ReportJobData | undefined;
    try {
      let jobInput = input;
      if (jobInput.exportId) {
        const { reportExport, companyId } = await this.reportsService.getExportForProcessing(
          jobInput.user,
          jobInput.exportId,
        );
        jobInput = {
          ...jobInput,
          companyId,
          user: {
            ...jobInput.user,
            companyId,
            activeCompanyId: companyId,
          },
        };
        verifiedInput = jobInput;
        await this.reportsService.markExportProcessing(reportExport.id, jobId);
      }
      const report = await this.reportsService.file(
        jobInput.user,
        jobInput.kind,
        jobInput.format,
        jobInput.companyId,
      );
      const stored = await this.storageService.uploadReport({
        originalname: report.fileName,
        mimetype: report.mimeType,
        size: report.buffer.length,
        buffer: report.buffer,
      });
      await this.notificationsService.create({
        userId: jobInput.user.sub,
        companyId: jobInput.companyId ?? null,
        title: 'Reporte listo para descargar',
        message: `${report.fileName}: ${stored.fileUrl}`,
        type: NotificationType.INFO,
        priority: NotificationPriority.MEDIUM,
        entity: 'Report',
        entityId: jobInput.exportId ?? jobId,
      });
      if (jobInput.exportId) {
        await this.reportsService.markExportReady(jobInput.exportId, stored);
      }
      await this.reportsService.logScheduledExport({
        user: jobInput.user,
        kind: jobInput.kind,
        format: jobInput.format,
        requestedCompanyId: jobInput.companyId,
        status: 'READY',
        jobId: jobInput.exportId ?? jobId,
        fileUrl: stored.fileUrl,
      });
      return stored;
    } catch (error) {
      if (verifiedInput?.exportId) {
        await this.reportsService.markExportFailed(verifiedInput.exportId, error);
      }
      if (verifiedInput) {
        await this.notificationsService.create({
          userId: verifiedInput.user.sub,
          companyId: verifiedInput.companyId ?? null,
          title: 'No fue posible generar el reporte',
          message: `${verifiedInput.kind}.${verifiedInput.format}: ${error instanceof Error ? error.message : String(error)}`,
          type: NotificationType.INFO,
          priority: NotificationPriority.HIGH,
          entity: 'Report',
          entityId: verifiedInput.exportId ?? jobId,
        });
        await this.reportsService.logScheduledExport({
          user: verifiedInput.user,
          kind: verifiedInput.kind,
          format: verifiedInput.format,
          requestedCompanyId: verifiedInput.companyId,
          status: 'FAILED',
          jobId: verifiedInput.exportId ?? jobId,
          error,
        });
      }
      throw error;
    }
  }
}

import { Controller, Get, Param, Post, Query, Req, Res, UseGuards } from '@nestjs/common';
import type { Request, Response } from 'express';
import { CurrentUser } from '../../common/decorators/current-user.decorator';
import { Roles } from '../../common/decorators/roles.decorator';
import { JwtAuthGuard } from '../../common/guards/jwt-auth.guard';
import { RolesGuard } from '../../common/guards/roles.guard';
import type { AuthenticatedUser } from '../../common/types/authenticated-request';
import { ReportExportsQueryDto } from './dto/report-exports-query.dto';
import { ReportsQueueService } from './reports-queue.service';
import type { ReportFormat, ReportKind } from './reports.service';
import { ReportsService } from './reports.service';
import { DocumentsStorageService } from '../documents/documents-storage.service';

@Controller('reports')
@UseGuards(JwtAuthGuard, RolesGuard)
export class ReportsController {
  constructor(
    private readonly reportsService: ReportsService,
    private readonly reportsQueueService: ReportsQueueService,
    private readonly documentsStorageService: DocumentsStorageService,
  ) {}

  @Get('exports')
  @Roles('ADMIN', 'SST', 'AUDITOR')
  findExports(@CurrentUser() user: AuthenticatedUser, @Query() query: ReportExportsQueryDto) {
    return this.reportsService.findExports(user, query);
  }

  @Get('metrics')
  @Roles('ADMIN', 'SST', 'AUDITOR')
  metrics(@CurrentUser() user: AuthenticatedUser, @Query() query: ReportExportsQueryDto) {
    return this.reportsService.metrics(user, query);
  }

  @Get('metrics/history')
  @Roles('ADMIN')
  metricHistory(@CurrentUser() user: AuthenticatedUser, @Query() query: ReportExportsQueryDto) {
    return this.reportsService.metricHistory(user, query);
  }

  @Post('exports/:id/retry')
  @Roles('ADMIN', 'SST', 'AUDITOR')
  async retryExport(@CurrentUser() user: AuthenticatedUser, @Param('id') id: string) {
    const reportExport = await this.reportsService.prepareRetry(user, id);
    return this.reportsQueueService.enqueue({
      user,
      kind: reportExport.kind,
      format: reportExport.format as ReportFormat,
      companyId: reportExport.requestedCompanyId ?? undefined,
      exportId: reportExport.id,
    });
  }

  @Get('exports/:id/download')
  @Roles('ADMIN', 'SST', 'AUDITOR')
  async downloadExport(
    @CurrentUser() user: AuthenticatedUser,
    @Param('id') id: string,
    @Res() response: Response,
  ) {
    const reportExport = await this.reportsService.getDownloadableExport(user, id);
    const content = await this.documentsStorageService.readReport(reportExport.storageKey!);
    response.setHeader('Content-Type', reportExport.mimeType ?? 'application/octet-stream');
    response.setHeader(
      'Content-Disposition',
      `attachment; filename*=UTF-8''${encodeURIComponent(reportExport.fileName!)}`,
    );
    response.send(content);
  }

  @Get(':kind.csv')
  @Roles('ADMIN', 'SST', 'AUDITOR')
  async csv(
    @CurrentUser() user: AuthenticatedUser,
    @Param('kind') kind: ReportKind,
    @Query('companyId') companyId: string | undefined,
    @Req() request: Request,
    @Res() response: Response,
  ) {
    const content = await this.generateAndAudit(() => this.reportsService.csv(user, kind, companyId), {
      user,
      kind,
      format: 'csv',
      companyId,
      request,
    });
    response.setHeader('Content-Type', 'text/csv; charset=utf-8');
    response.setHeader('Content-Disposition', `attachment; filename="${kind}.csv"`);
    response.send(content);
  }

  @Get(':kind.pdf')
  @Roles('ADMIN', 'SST', 'AUDITOR')
  async pdf(
    @CurrentUser() user: AuthenticatedUser,
    @Param('kind') kind: ReportKind,
    @Query('companyId') companyId: string | undefined,
    @Req() request: Request,
    @Res() response: Response,
  ) {
    const content = await this.generateAndAudit(() => this.reportsService.pdf(user, kind, companyId), {
      user,
      kind,
      format: 'pdf',
      companyId,
      request,
    });
    response.setHeader('Content-Type', 'application/pdf');
    response.setHeader('Content-Disposition', `attachment; filename="${kind}.pdf"`);
    response.send(content);
  }

  @Post(':kind.:format/schedule')
  @Roles('ADMIN', 'SST', 'AUDITOR')
  schedule(
    @CurrentUser() user: AuthenticatedUser,
    @Param('kind') kind: ReportKind,
    @Param('format') format: ReportFormat,
    @Query('companyId') companyId: string | undefined,
  ) {
    return this.reportsQueueService.enqueue({ user, kind, format, companyId });
  }

  private async generateAndAudit<T>(
    action: () => Promise<T>,
    metadata: {
      user: AuthenticatedUser;
      kind: string;
      format: ReportFormat;
      companyId?: string;
      request: Request;
    },
  ) {
    try {
      const content = await action();
      await this.reportsService.logExport({
        user: metadata.user,
        kind: metadata.kind,
        format: metadata.format,
        requestedCompanyId: metadata.companyId,
        request: metadata.request,
        status: 'SUCCESS',
      });
      return content;
    } catch (error) {
      await this.reportsService.logExport({
        user: metadata.user,
        kind: metadata.kind,
        format: metadata.format,
        requestedCompanyId: metadata.companyId,
        request: metadata.request,
        status: 'FAILED',
        error,
      });
      throw error;
    }
  }
}

import {
  BadRequestException,
  ForbiddenException,
  Injectable,
} from '@nestjs/common';
import {
  IncidentStatus,
  Prisma,
  ReportExportStatus,
  RiskLevel,
  Role,
} from '@prisma/client';
import type { Request } from 'express';
import PDFDocument from 'pdfkit';
import type { AuthenticatedUser } from '../../common/types/authenticated-request';
import { resolveCompanyScope } from '../../common/pipes/company-scope';
import { env } from '../../config/env';
import { PrismaService } from '../../database/prisma.service';
import { AuditService } from '../audit/audit.service';
import { ReportExportsQueryDto } from './dto/report-exports-query.dto';

export type ReportKind =
  'employees' | 'expired-documents' | 'audits' | 'summary';
export type ReportFormat = 'csv' | 'pdf';
type ExportWhereBuildOptions = {
  includeSearch?: boolean;
  includeStatusFilter?: boolean;
};
type MetricAlertKind = 'FAILURE_RATE' | 'STORAGE';
const reportKinds: ReportKind[] = [
  'employees',
  'expired-documents',
  'audits',
  'summary',
];
const reportFormats: ReportFormat[] = ['csv', 'pdf'];

@Injectable()
export class ReportsService {
  constructor(
    private readonly prisma: PrismaService,
    private readonly auditService: AuditService,
  ) {}

  async csv(user: AuthenticatedUser, kind: ReportKind, companyId?: string) {
    this.assertReportKind(kind);
    const rows = await this.getRows(user, kind, companyId);
    return this.toCsv(rows);
  }

  async pdf(user: AuthenticatedUser, kind: ReportKind, companyId?: string) {
    this.assertReportKind(kind);
    const rows = await this.getRows(user, kind, companyId);
    return this.toPdf(this.reportTitle(kind), rows);
  }

  async file(
    user: AuthenticatedUser,
    kind: string,
    format: ReportFormat,
    companyId?: string,
  ) {
    this.assertReportKind(kind);
    this.assertReportFormat(format);
    if (format === 'csv') {
      const content = await this.csv(user, kind, companyId);
      return {
        buffer: Buffer.from(content, 'utf8'),
        fileName: `${kind}-${new Date().toISOString().slice(0, 10)}.csv`,
        mimeType: 'text/csv',
      };
    }
    const content = await this.pdf(user, kind, companyId);
    return {
      buffer: content,
      fileName: `${kind}-${new Date().toISOString().slice(0, 10)}.pdf`,
      mimeType: 'application/pdf',
    };
  }

  async findExports(user: AuthenticatedUser, query: ReportExportsQueryDto) {
    await this.expireOldExports();
    const page = query.page ?? 1;
    const pageSize = query.pageSize ?? 10;
    const where = this.buildExportsWhere(user, query, {
      includeSearch: true,
      includeStatusFilter: true,
    });
    const [data, total] = await this.prisma.$transaction([
      this.prisma.reportExport.findMany({
        where,
        include: {
          company: { select: { id: true, name: true, nit: true } },
          requestedBy: {
            select: { id: true, name: true, email: true, role: true },
          },
        },
        orderBy: { createdAt: 'desc' },
        skip: (page - 1) * pageSize,
        take: pageSize,
      }),
      this.prisma.reportExport.count({ where }),
    ]);
    return {
      data,
      meta: { page, pageSize, total, totalPages: Math.ceil(total / pageSize) },
    };
  }

  async metrics(user: AuthenticatedUser, query: ReportExportsQueryDto) {
    await this.expireOldExports();
    const where = this.buildExportsWhere(user, query, {
      includeSearch: true,
      includeStatusFilter: false,
    });
    const metrics = await this.computeExportMetrics(where);
    // Los exportes de plataforma (sin empresa) solo son visibles para SUPER_ADMIN.
    if (user.role !== 'SUPER_ADMIN') {
      const platformTotals = await this.computeExportMetrics({
        ...where,
        companyId: null,
      });
      metrics.totals = {
        total: metrics.totals.total - platformTotals.totals.total,
        queued: metrics.totals.queued - platformTotals.totals.queued,
        processing:
          metrics.totals.processing - platformTotals.totals.processing,
        ready: metrics.totals.ready - platformTotals.totals.ready,
        failed: metrics.totals.failed - platformTotals.totals.failed,
        expired: metrics.totals.expired - platformTotals.totals.expired,
        storageBytes:
          metrics.totals.storageBytes - platformTotals.totals.storageBytes,
        averageGenerationSeconds: metrics.totals.averageGenerationSeconds,
      };
    }
    return metrics;
  }

  async metricHistory(user: AuthenticatedUser, query: ReportExportsQueryDto) {
    const dateRange = this.requestedAtRange(query.dateFrom, query.dateTo);
    const companyId = resolveCompanyScope(user, query.companyId);
    const snapshots = await this.prisma.reportExportMetricSnapshot.findMany({
      where: {
        ...(companyId
          ? { companyId }
          : user.role === 'SUPER_ADMIN'
            ? {}
            : { companyId: null }),
        ...(dateRange ? { date: dateRange } : {}),
      },
      include: { company: { select: { id: true, name: true, nit: true } } },
      orderBy: { date: 'asc' },
      take: 60,
    });
    return snapshots;
  }

  async captureDailyMetricSnapshots(date = this.previousDayStart()) {
    const dayRange = {
      gte: date,
      lte: this.endOfDay(date.toISOString()),
    };
    const companies = await this.prisma.company.findMany({
      where: { isActive: true },
      select: { id: true },
    });
    const scopes: Array<{ scopeKey: string; companyId?: string }> = [
      { scopeKey: 'platform' },
      ...companies.map((company) => ({
        scopeKey: `company:${company.id}`,
        companyId: company.id,
      })),
    ];

    let written = 0;
    for (const scope of scopes) {
      const metrics = await this.computeExportMetrics({
        requestedAt: dayRange,
        ...(scope.companyId ? { companyId: scope.companyId } : {}),
      });
      await this.prisma.reportExportMetricSnapshot.upsert({
        where: { date_scopeKey: { date, scopeKey: scope.scopeKey } },
        create: {
          date,
          scopeKey: scope.scopeKey,
          companyId: scope.companyId,
          ...metrics.totals,
        },
        update: {
          companyId: scope.companyId,
          ...metrics.totals,
        },
      });
      written += 1;
    }

    await this.auditService.log({
      action: 'CAPTURE_REPORT_EXPORT_METRICS',
      entity: 'ReportExportMetricSnapshot',
      after: { date: date.toISOString().slice(0, 10), written },
    });
    return { success: true, date: date.toISOString().slice(0, 10), written };
  }

  async metricAlertCandidates(date = this.previousDayStart()) {
    if (!env.reportAlertsEnabled) {
      return [];
    }
    const snapshots = await this.prisma.reportExportMetricSnapshot.findMany({
      where: { date },
      include: {
        company: {
          select: {
            id: true,
            name: true,
            reportFailureRateAlertPercent: true,
            reportStorageAlertBytes: true,
          },
        },
      },
      orderBy: { companyId: 'asc' },
    });

    return snapshots.flatMap((snapshot) => {
      const alerts: Array<{
        kind: MetricAlertKind;
        snapshotId: string;
        companyId: string | null;
        companyName: string;
        title: string;
        message: string;
      }> = [];
      const failureRate = snapshot.total
        ? Math.round((snapshot.failed / snapshot.total) * 100)
        : 0;
      const scopeName = snapshot.company?.name ?? 'Plataforma';
      const failureRateThreshold =
        snapshot.company?.reportFailureRateAlertPercent ??
        env.reportFailureRateAlertPercent;
      const storageThreshold =
        snapshot.company?.reportStorageAlertBytes ??
        env.reportStorageAlertBytes;
      if (
        snapshot.total > 0 &&
        failureRateThreshold > 0 &&
        failureRate >= failureRateThreshold
      ) {
        alerts.push({
          kind: 'FAILURE_RATE',
          snapshotId: snapshot.id,
          companyId: snapshot.companyId,
          companyName: scopeName,
          title: 'Alerta por fallos en reportes',
          message: `${scopeName}: tasa de fallos ${failureRate}% (${snapshot.failed}/${snapshot.total}); umbral ${failureRateThreshold}%`,
        });
      }
      if (storageThreshold > 0 && snapshot.storageBytes >= storageThreshold) {
        alerts.push({
          kind: 'STORAGE',
          snapshotId: snapshot.id,
          companyId: snapshot.companyId,
          companyName: scopeName,
          title: 'Alerta por almacenamiento de reportes',
          message: `${scopeName}: ${snapshot.storageBytes} bytes usados en reportes generados; umbral ${storageThreshold} bytes`,
        });
      }
      return alerts;
    });
  }

  async metricAlertTargets(companyId?: string | null) {
    return this.prisma.user.findMany({
      where: {
        isActive: true,
        ...(companyId
          ? {
              OR: [
                { role: Role.ADMIN, companyId: null },
                { role: Role.ADMIN, companyId },
                { role: Role.SST, companyId },
              ],
            }
          : { role: Role.ADMIN }),
      },
      select: { id: true, companyId: true, role: true },
    });
  }

  async logMetricAlertEvaluation(input: {
    date: string;
    alerts: number;
    notifications: number;
  }) {
    await this.auditService.log({
      action: 'EVALUATE_REPORT_EXPORT_ALERTS',
      entity: 'ReportExportMetricSnapshot',
      after: input,
    });
  }

  private async computeExportMetrics(where: Prisma.ReportExportWhereInput) {
    const records = await this.prisma.reportExport.findMany({
      where,
      select: {
        status: true,
        companyId: true,
        kind: true,
        size: true,
        startedAt: true,
        completedAt: true,
      },
      orderBy: { createdAt: 'desc' },
      take: 5000,
    });

    const companyIds = Array.from(
      new Set(
        records
          .map((item) => item.companyId)
          .filter((value): value is string => Boolean(value)),
      ),
    );
    const companies = companyIds.length
      ? await this.prisma.company.findMany({
          where: { id: { in: companyIds } },
          select: { id: true, name: true },
        })
      : [];
    const companyNameById = new Map(
      companies.map((item) => [item.id, item.name]),
    );
    const statusCountByKey = new Map<ReportExportStatus, number>();
    const companyTotals = new Map<
      string,
      { companyId: string | null; total: number; storageBytes: number }
    >();
    const failuresByKind = new Map<string, number>();
    let totalStorageBytes = 0;
    let totalGenerationMs = 0;
    let timedCount = 0;

    for (const item of records) {
      statusCountByKey.set(
        item.status,
        (statusCountByKey.get(item.status) ?? 0) + 1,
      );
      const companyKey = item.companyId ?? 'none';
      const currentCompany = companyTotals.get(companyKey) ?? {
        companyId: item.companyId,
        total: 0,
        storageBytes: 0,
      };
      currentCompany.total += 1;
      currentCompany.storageBytes += item.size ?? 0;
      companyTotals.set(companyKey, currentCompany);

      if (item.status === ReportExportStatus.FAILED) {
        failuresByKind.set(item.kind, (failuresByKind.get(item.kind) ?? 0) + 1);
      }
      totalStorageBytes += item.size ?? 0;
      if (item.startedAt && item.completedAt) {
        totalGenerationMs += Math.max(
          item.completedAt.getTime() - item.startedAt.getTime(),
          0,
        );
        timedCount += 1;
      }
    }

    const averageGenerationSeconds = timedCount
      ? Math.round(totalGenerationMs / timedCount / 1000)
      : 0;

    return {
      totals: {
        total: records.length,
        queued: statusCountByKey.get(ReportExportStatus.QUEUED) ?? 0,
        processing: statusCountByKey.get(ReportExportStatus.PROCESSING) ?? 0,
        ready: statusCountByKey.get(ReportExportStatus.READY) ?? 0,
        failed: statusCountByKey.get(ReportExportStatus.FAILED) ?? 0,
        expired: statusCountByKey.get(ReportExportStatus.EXPIRED) ?? 0,
        storageBytes: totalStorageBytes,
        averageGenerationSeconds,
      },
      byCompany: Array.from(companyTotals.values())
        .map((item) => ({
          companyId: item.companyId,
          companyName: item.companyId
            ? (companyNameById.get(item.companyId) ?? 'Empresa no encontrada')
            : 'Sin empresa',
          total: item.total,
          storageBytes: item.storageBytes,
        }))
        .sort((a, b) => b.total - a.total)
        .slice(0, 10),
      failuresByKind: Array.from(failuresByKind.entries())
        .map(([kind, failed]) => ({ kind, failed }))
        .sort((a, b) => b.failed - a.failed),
    };
  }

  async createExport(input: {
    user: AuthenticatedUser;
    kind: string;
    format: ReportFormat;
    companyId?: string;
  }) {
    this.assertReportKind(input.kind);
    this.assertReportFormat(input.format);
    const companyId = this.auditCompanyId(input.user, input.companyId);
    return this.prisma.reportExport.create({
      data: {
        kind: input.kind,
        format: input.format,
        requestedCompanyId: input.companyId,
        companyId,
        requestedById: input.user.sub,
        status: ReportExportStatus.QUEUED,
        expiresAt: await this.defaultExpiration(companyId),
      },
    });
  }

  async prepareRetry(user: AuthenticatedUser, id: string) {
    const current = await this.findOwnedExport(user, id);
    if (
      current.status !== ReportExportStatus.FAILED &&
      current.status !== ReportExportStatus.EXPIRED
    ) {
      throw new BadRequestException(
        'Only failed or expired report exports can be retried',
      );
    }
    return this.prisma.reportExport.update({
      where: { id },
      data: {
        status: ReportExportStatus.QUEUED,
        fileUrl: null,
        fileName: null,
        mimeType: null,
        storageKey: null,
        size: null,
        jobId: null,
        error: null,
        startedAt: null,
        completedAt: null,
        expiresAt: await this.defaultExpiration(current?.companyId),
      },
    });
  }

  async getDownloadableExport(user: AuthenticatedUser, id: string) {
    const reportExport = await this.findOwnedExport(user, id);
    if (
      reportExport.status !== ReportExportStatus.READY ||
      !reportExport.storageKey ||
      !reportExport.fileName
    ) {
      throw new BadRequestException(
        'Report export is not available for download',
      );
    }
    return reportExport;
  }

  async getExportForProcessing(user: AuthenticatedUser, id: string) {
    const reportExport = await this.prisma.reportExport.findUnique({
      where: { id },
    });
    // El exporte pertenece a quien lo solicitó; para SUPER_ADMIN se exige que la empresa
    // del exporte coincida con la empresa activa seleccionada (o que no tenga empresa,
    // exportes de plataforma).
    const activeCompany =
      user.role === 'SUPER_ADMIN' ? (user.activeCompanyId ?? null) : null;
    const ownershipValid =
      reportExport &&
      reportExport.requestedById === user.sub &&
      !!reportExport.companyId &&
      (user.role !== 'SUPER_ADMIN' || reportExport.companyId === activeCompany);
    if (!ownershipValid) {
      throw new BadRequestException(
        'Report export is not available for processing',
      );
    }
    const companyId = resolveCompanyScope(user, reportExport.companyId);
    return { reportExport, companyId };
  }

  async markExportQueued(id: string, jobId?: string) {
    return this.prisma.reportExport.update({
      where: { id },
      data: { status: ReportExportStatus.QUEUED, jobId },
    });
  }

  async markExportProcessing(id: string, jobId?: string) {
    return this.prisma.reportExport.update({
      where: { id },
      data: {
        status: ReportExportStatus.PROCESSING,
        startedAt: new Date(),
        jobId,
      },
    });
  }

  async markExportReady(
    id: string,
    stored: {
      fileUrl: string;
      fileName: string;
      mimeType: string;
      size: number;
      storageKey?: string;
    },
  ) {
    const current = await this.prisma.reportExport.findUnique({
      where: { id },
      select: { companyId: true },
    });
    return this.prisma.reportExport.update({
      where: { id },
      data: {
        status: ReportExportStatus.READY,
        fileUrl: stored.fileUrl,
        fileName: stored.fileName,
        mimeType: stored.mimeType,
        size: stored.size,
        storageKey: stored.storageKey,
        completedAt: new Date(),
        expiresAt: await this.defaultExpiration(current?.companyId),
        error: null,
      },
    });
  }

  async markExportFailed(id: string, error: unknown) {
    return this.prisma.reportExport.update({
      where: { id },
      data: {
        status: ReportExportStatus.FAILED,
        error: this.errorMessage(error),
        completedAt: new Date(),
      },
    });
  }

  async cleanupExpiredExports(
    deleteFile: (storageKey: string) => Promise<unknown>,
  ) {
    await this.expireOldExports();
    const retentionCutoff = new Date(
      Date.now() -
        Math.max(env.reportExportRetentionDays, 0) * 24 * 60 * 60 * 1000,
    );
    const expiredExports = await this.prisma.reportExport.findMany({
      where: {
        status: ReportExportStatus.EXPIRED,
        storageKey: { not: null },
      },
      select: { id: true, storageKey: true },
      take: 100,
    });

    let deleted = 0;
    let failed = 0;
    const deletedIds: string[] = [];
    for (const reportExport of expiredExports) {
      if (!reportExport.storageKey) continue;
      if (!(await this.isPastRetention(reportExport.id, retentionCutoff)))
        continue;
      try {
        await deleteFile(reportExport.storageKey);
        deleted += 1;
        deletedIds.push(reportExport.id);
      } catch {
        failed += 1;
      }
    }

    if (deletedIds.length > 0) {
      await this.prisma.reportExport.updateMany({
        where: { id: { in: deletedIds } },
        data: {
          fileUrl: null,
          storageKey: null,
          size: null,
        },
      });
    }

    await this.auditService.log({
      action: 'CLEANUP_EXPIRED_REPORT_EXPORTS',
      entity: 'ReportExport',
      after: {
        scanned: expiredExports.length,
        deleted,
        failed,
        retentionDays: env.reportExportRetentionDays,
      },
    });

    return { success: true, scanned: expiredExports.length, deleted, failed };
  }

  logExport(input: {
    user: AuthenticatedUser;
    kind: string;
    format: ReportFormat;
    requestedCompanyId?: string;
    request: Request;
    status: 'SUCCESS' | 'FAILED';
    error?: unknown;
  }) {
    return this.auditService.log({
      user: input.user,
      action: input.status === 'SUCCESS' ? 'EXPORT' : 'EXPORT_FAILED',
      entity: 'Report',
      entityId: input.kind,
      after: {
        kind: input.kind,
        format: input.format,
        status: input.status,
        companyId: this.auditCompanyId(input.user, input.requestedCompanyId),
        requestedCompanyId: input.requestedCompanyId ?? null,
        ip: input.request.ip,
        userAgent: input.request.get('user-agent') ?? '',
        error: input.error ? this.errorMessage(input.error) : null,
      },
    });
  }

  logScheduledExport(input: {
    user: AuthenticatedUser;
    kind: string;
    format: ReportFormat;
    requestedCompanyId?: string;
    status: 'QUEUED' | 'READY' | 'FAILED';
    jobId?: string;
    fileUrl?: string;
    error?: unknown;
  }) {
    return this.auditService.log({
      user: input.user,
      action:
        input.status === 'QUEUED'
          ? 'EXPORT_QUEUED'
          : input.status === 'READY'
            ? 'EXPORT_READY'
            : 'EXPORT_FAILED',
      entity: 'Report',
      entityId: input.kind,
      after: {
        kind: input.kind,
        format: input.format,
        status: input.status,
        jobId: input.jobId ?? null,
        fileUrl: input.fileUrl ?? null,
        companyId: this.auditCompanyId(input.user, input.requestedCompanyId),
        requestedCompanyId: input.requestedCompanyId ?? null,
        error: input.error ? this.errorMessage(input.error) : null,
      },
    });
  }

  private async getRows(
    user: AuthenticatedUser,
    kind: ReportKind,
    companyId?: string,
  ) {
    const scopedCompanyId = this.resolveCompanyId(user, companyId);
    const companyScope = scopedCompanyId ? { companyId: scopedCompanyId } : {};

    if (kind === 'employees') {
      const employees = await this.prisma.employee.findMany({
        where: { ...companyScope, isActive: true },
        include: { company: { select: { name: true, nit: true } } },
        orderBy: { createdAt: 'desc' },
      });
      return employees.map((item) => ({
        empresa: item.company.name,
        nit: item.company.nit,
        empleado: `${item.firstName} ${item.lastName}`,
        documento: item.document,
        cargo: item.position,
        centroTrabajo: item.workCenter ?? '',
        estado: item.employmentStatus,
      }));
    }

    if (kind === 'expired-documents') {
      const now = new Date();
      const documents = await this.prisma.document.findMany({
        where: { ...companyScope, isActive: true, expiresAt: { lt: now } },
        include: { company: { select: { name: true, nit: true } } },
        orderBy: { expiresAt: 'asc' },
      });
      return documents.map((item) => ({
        empresa: item.company.name,
        nit: item.company.nit,
        documento: item.name,
        categoria: item.category,
        estado: item.status,
        vencimiento: item.expiresAt?.toISOString().slice(0, 10) ?? '',
        version: item.version,
      }));
    }

    if (kind === 'audits') {
      const audits = await this.prisma.audit.findMany({
        where: { ...companyScope, isActive: true },
        include: {
          company: { select: { name: true, nit: true } },
          findings: { include: { actions: true } },
        },
        orderBy: { scheduledAt: 'desc' },
      });
      return audits.map((item) => ({
        empresa: item.company.name,
        nit: item.company.nit,
        auditoria: item.title,
        estado: item.status,
        auditor: item.auditorName ?? '',
        fecha: item.scheduledAt.toISOString().slice(0, 10),
        hallazgos: item.findings.length,
        acciones: item.findings.reduce(
          (total, finding) => total + finding.actions.length,
          0,
        ),
      }));
    }

    const [employees, criticalRisks, openIncidents, expiredDocuments, audits] =
      await this.prisma.$transaction([
        this.prisma.employee.count({
          where: { ...companyScope, isActive: true },
        }),
        this.prisma.risk.count({
          where: { ...companyScope, level: RiskLevel.CRITICAL },
        }),
        this.prisma.incident.count({
          where: { ...companyScope, status: { not: IncidentStatus.RESOLVED } },
        }),
        this.prisma.document.count({
          where: {
            ...companyScope,
            isActive: true,
            expiresAt: { lt: new Date() },
          },
        }),
        this.prisma.audit.count({ where: { ...companyScope, isActive: true } }),
      ]);
    return [
      {
        empleadosActivos: employees,
        riesgosCriticos: criticalRisks,
        incidentesAbiertos: openIncidents,
        documentosVencidos: expiredDocuments,
        auditoriasActivas: audits,
      },
    ];
  }

  private resolveCompanyId(user: AuthenticatedUser, companyId?: string) {
    return resolveCompanyScope(user, companyId);
  }

  private auditCompanyId(user: AuthenticatedUser, requestedCompanyId?: string) {
    return resolveCompanyScope(user, requestedCompanyId);
  }

  private assertReportKind(kind: string): asserts kind is ReportKind {
    if (!reportKinds.includes(kind as ReportKind)) {
      throw new BadRequestException('Unsupported report type');
    }
  }

  private assertReportFormat(format: string): asserts format is ReportFormat {
    if (!reportFormats.includes(format as ReportFormat)) {
      throw new BadRequestException('Unsupported report format');
    }
  }

  private async findOwnedExport(user: AuthenticatedUser, id: string) {
    const reportExport = await this.prisma.reportExport.findUnique({
      where: { id },
    });
    if (!reportExport || !this.canAccessExport(user, reportExport)) {
      throw new BadRequestException('Report export not found');
    }
    return reportExport;
  }

  private async expireOldExports() {
    await this.prisma.reportExport.updateMany({
      where: {
        status: ReportExportStatus.READY,
        expiresAt: { lt: new Date() },
      },
      data: { status: ReportExportStatus.EXPIRED },
    });
  }

  private async defaultExpiration(companyId?: string | null) {
    const company = companyId
      ? await this.prisma.company.findUnique({
          where: { id: companyId },
          select: { reportExportExpirationDays: true },
        })
      : null;
    const days =
      company?.reportExportExpirationDays ?? env.reportExportExpirationDays;
    return new Date(Date.now() + Math.max(days, 1) * 24 * 60 * 60 * 1000);
  }

  private statusSearch(search: string) {
    const upper = search.toUpperCase();
    return Object.values(ReportExportStatus).includes(
      upper as ReportExportStatus,
    )
      ? (upper as ReportExportStatus)
      : undefined;
  }

  private errorMessage(error: unknown) {
    if (error instanceof Error) return error.message;
    return String(error);
  }

  private exportVisibilityWhere(
    user: AuthenticatedUser,
  ): Prisma.ReportExportWhereInput {
    if (user.role === 'SUPER_ADMIN') {
      return user.activeCompanyId ? { companyId: user.activeCompanyId } : {};
    }
    return { requestedById: user.sub };
  }

  private buildExportsWhere(
    user: AuthenticatedUser,
    query: ReportExportsQueryDto,
    options: ExportWhereBuildOptions,
  ): Prisma.ReportExportWhereInput {
    const search = query.search?.trim();
    const statusFromSearch = search ? this.statusSearch(search) : undefined;
    const dateRange = this.requestedAtRange(query.dateFrom, query.dateTo);
    return {
      ...this.exportVisibilityWhere(user),
      ...(options.includeStatusFilter && query.status
        ? { status: query.status as ReportExportStatus }
        : {}),
      ...(this.canFilterCompany(user) && query.companyId
        ? { companyId: query.companyId }
        : {}),
      ...(this.canFilterRequester(user) && query.requestedById
        ? { requestedById: query.requestedById }
        : {}),
      ...(dateRange ? { requestedAt: dateRange } : {}),
      ...(options.includeSearch && search
        ? {
            OR: [
              { kind: { contains: search, mode: 'insensitive' } },
              { format: { contains: search, mode: 'insensitive' } },
              ...(statusFromSearch
                ? [{ status: { equals: statusFromSearch } }]
                : []),
              { fileName: { contains: search, mode: 'insensitive' } },
            ],
          }
        : {}),
    };
  }

  private canFilterCompany(user: AuthenticatedUser) {
    return user.role === 'SUPER_ADMIN';
  }

  private canFilterRequester(user: AuthenticatedUser) {
    return user.role === 'SUPER_ADMIN';
  }

  private canAccessExport(
    user: AuthenticatedUser,
    reportExport: { requestedById: string; companyId: string | null },
  ) {
    if (reportExport.requestedById === user.sub) return true;
    if (user.role !== 'SUPER_ADMIN') return false;
    return user.activeCompanyId
      ? reportExport.companyId === user.activeCompanyId
      : true;
  }

  private async isPastRetention(id: string, defaultRetentionCutoff: Date) {
    const reportExport = await this.prisma.reportExport.findUnique({
      where: { id },
      select: {
        expiresAt: true,
        company: { select: { reportExportRetentionDays: true } },
      },
    });
    if (!reportExport?.expiresAt) return false;
    const retentionDays =
      reportExport.company?.reportExportRetentionDays ??
      env.reportExportRetentionDays;
    const cutoff = new Date(
      Date.now() - Math.max(retentionDays, 0) * 24 * 60 * 60 * 1000,
    );
    return (
      reportExport.expiresAt <
      (reportExport.company ? cutoff : defaultRetentionCutoff)
    );
  }

  private requestedAtRange(
    dateFrom?: string,
    dateTo?: string,
  ): Prisma.DateTimeFilter | undefined {
    if (!dateFrom && !dateTo) return undefined;
    return {
      ...(dateFrom ? { gte: new Date(dateFrom) } : {}),
      ...(dateTo ? { lte: this.endOfDay(dateTo) } : {}),
    };
  }

  private endOfDay(value: string) {
    const date = new Date(value);
    date.setUTCHours(23, 59, 59, 999);
    return date;
  }

  private previousDayStart() {
    const date = new Date();
    date.setUTCDate(date.getUTCDate() - 1);
    date.setUTCHours(0, 0, 0, 0);
    return date;
  }

  private toCsv(rows: Array<Record<string, unknown>>) {
    if (rows.length === 0) return '';
    const headers = Object.keys(rows[0]);
    const lines = [
      headers.join(','),
      ...rows.map((row) =>
        headers.map((header) => this.escapeCsv(row[header])).join(','),
      ),
    ];
    return lines.join('\n');
  }

  private escapeCsv(value: unknown) {
    const text = String(value ?? '');
    return `"${text.replace(/"/g, '""')}"`;
  }

  private toPdf(title: string, rows: Array<Record<string, unknown>>) {
    return new Promise<Buffer>((resolve) => {
      const doc = new PDFDocument({ margin: 40, size: 'A4' });
      const chunks: Buffer[] = [];
      doc.on('data', (chunk: Buffer) => chunks.push(chunk));
      doc.on('end', () => resolve(Buffer.concat(chunks)));

      doc.fontSize(18).text(title);
      doc.fontSize(10).text(`Generado: ${new Date().toISOString()}`);
      doc.moveDown();

      if (rows.length === 0) {
        doc.text('Sin datos para el reporte.');
      } else {
        rows.forEach((row, index) => {
          doc
            .fontSize(12)
            .text(
              `${index + 1}. ${Object.values(row).slice(0, 2).join(' - ')}`,
            );
          doc.fontSize(9);
          Object.entries(row).forEach(([key, value]) => {
            doc.text(`${key}: ${String(value ?? '')}`);
          });
          doc.moveDown();
        });
      }
      doc.end();
    });
  }

  private reportTitle(kind: ReportKind) {
    const titles: Record<ReportKind, string> = {
      employees: 'Reporte de empleados',
      'expired-documents': 'Reporte de documentos vencidos',
      audits: 'Reporte de auditorias SG-SST',
      summary: 'Resumen ejecutivo SG-SST',
    };
    return titles[kind];
  }
}

import {
  BadRequestException,
  ConflictException,
  ForbiddenException,
  Injectable,
  NotFoundException,
} from '@nestjs/common';
import * as bcrypt from 'bcrypt';
import { ListQueryDto } from '../../common/dto/list-query.dto';
import type { AuthenticatedUser } from '../../common/types/authenticated-request';
import { assertCompanyScope } from '../../common/pipes/company-scope';
import { AuditService } from '../audit/audit.service';
import { CreateUserDto } from './dto/create-user.dto';
import { UpdateUserDto } from './dto/update-user.dto';
import { UsersRepository } from './users.repository';

@Injectable()
export class UsersService {
  constructor(
    private readonly usersRepository: UsersRepository,
    private readonly auditService: AuditService,
  ) {}

  findAll(companyId?: string, query: ListQueryDto = new ListQueryDto()) {
    return this.usersRepository.findAll(companyId, query);
  }

  async findOne(id: string, actor?: AuthenticatedUser) {
    // Aislamiento por empresa: el usuario de otra empresa no existe para el actor.
    // SUPER_ADMIN (sin companyId en su cuenta) conserva la búsqueda global;
    // el assert posterior valida el scope de la empresa encontrada.
    const user =
      actor && actor.companyId
        ? await this.usersRepository.findByIdScoped(id, actor.companyId)
        : await this.usersRepository.findById(id);
    if (!user) {
      throw new NotFoundException('User not found');
    }
    if (actor && user.companyId) {
      assertCompanyScope(actor, user.companyId);
    }
    return user;
  }

  async create(dto: CreateUserDto, actor?: AuthenticatedUser) {
    this.assertUserAssignmentScope(actor, dto.role, dto.companyId);
    const existing = await this.usersRepository.findByEmail(dto.email);
    if (existing) {
      throw new ConflictException('Email is already registered');
    }

    this.ensureSingleCompanyAssignment(dto.role, dto.companyId);

    const passwordHash = await bcrypt.hash(dto.password, 12);
    const created = await this.usersRepository.create(dto, passwordHash);
    await this.auditService.log({
      user: actor,
      action: 'CREATE',
      entity: 'User',
      entityId: created.id,
      after: created,
    });
    return created;
  }

  async update(id: string, dto: UpdateUserDto, actor?: AuthenticatedUser) {
    const before = await this.findOne(id, actor);
    this.assertUserAssignmentScope(
      actor,
      dto.role ?? before.role,
      dto.companyId ?? before.companyId,
    );
    this.ensureSingleCompanyAssignment(
      dto.role ?? before.role,
      dto.companyId ?? before.companyId,
    );
    // Update restrictivo: solo afecta usuarios dentro del scope de empresa del actor.
    if (actor?.companyId) {
      const result = await this.usersRepository.updateScoped(
        id,
        actor.companyId,
        dto,
      );
      if (result.count === 0) {
        throw new NotFoundException('User not found');
      }
    } else {
      await this.usersRepository.update(id, dto);
    }
    const updated = await this.findOne(id, actor);
    await this.auditService.log({
      user: actor,
      action: this.resolveStateAction(before.isActive, dto.isActive),
      entity: 'User',
      entityId: id,
      before,
      after: updated,
    });
    return updated;
  }

  async remove(id: string, actor?: AuthenticatedUser) {
    const before = await this.findOne(id, actor);
    if (actor?.companyId) {
      const result = await this.usersRepository.removeScoped(
        id,
        actor.companyId,
      );
      if (result.count === 0) {
        throw new NotFoundException('User not found');
      }
    } else {
      await this.usersRepository.remove(id);
    }
    const updated = await this.findOne(id, actor);
    await this.auditService.log({
      user: actor,
      action: 'DEACTIVATE',
      entity: 'User',
      entityId: id,
      before,
      after: updated,
    });
    return updated;
  }

  private ensureSingleCompanyAssignment(
    role: string,
    companyId?: string | null,
  ) {
    const isSuperAdmin = role === 'SUPER_ADMIN';
    if (isSuperAdmin) {
      if (companyId) {
        throw new BadRequestException(
          'SUPER_ADMIN cannot be assigned to a company',
        );
      }
      return;
    }

    if (!companyId) {
      throw new BadRequestException(
        'Users with company roles must belong to one company',
      );
    }
  }

  private assertUserAssignmentScope(
    actor: AuthenticatedUser | undefined,
    role: string,
    companyId?: string | null,
  ) {
    if (!actor) return;
    if (role === 'SUPER_ADMIN') {
      if (actor.role !== 'SUPER_ADMIN') {
        throw new ForbiddenException(
          'Only SUPER_ADMIN can manage SUPER_ADMIN users',
        );
      }
      return;
    }
    assertCompanyScope(actor, companyId);
  }

  private resolveStateAction(beforeActive: boolean, nextActive?: boolean) {
    if (nextActive === true && !beforeActive) {
      return 'REACTIVATE';
    }
    if (nextActive === false && beforeActive) {
      return 'DEACTIVATE';
    }
    return 'UPDATE';
  }
}

